package net.civeira.phylax.feature.access.oauthclient.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.oauthclient.domain.OauthClient;
import net.civeira.phylax.feature.access.oauthclient.domain.valueobject.CodeVO;

class CodeValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of code of oauth client")
  void test_code_value_holder_assign_plain_value() {
    Object holder = new Object();
    CodeValueHolder<Object> value = new CodeValueHolder<>(holder);
    Assertions.assertSame(holder, value.code("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getCodeValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getCode().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of code of oauth client")
  void test_code_value_holder_assign_value_object() {
    Object holder = new Object();
    CodeValueHolder<Object> value = new CodeValueHolder<>(holder);
    CodeVO vo = CodeVO.from("one");
    Assertions.assertFalse(value.getCodeValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.code(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getCodeValue().orElseThrow());
    Assertions.assertSame(holder, value.code(Optional.empty()));
    Assertions.assertFalse(value.getCodeValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.code(Optional.of(vo)));
    Assertions.assertSame(vo, value.getCodeValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of code of oauth client against the original")
  void test_code_value_holder_read() {
    Object holder = new Object();
    CodeValueHolder<Object> value = new CodeValueHolder<>(holder);
    CodeVO vo = CodeVO.from("one");
    CodeVO other = CodeVO.from("one");
    OauthClient original = Mockito.mock(OauthClient.class);
    Mockito.when(original.getCodeValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readCode(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readCode(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.code(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readCode(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readCode(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of code of oauth client")
  void test_code_value_holder_unset() {
    Object holder = new Object();
    CodeValueHolder<Object> value = new CodeValueHolder<>(holder);
    CodeVO vo = CodeVO.from("one");
    value.code(vo);
    Assertions.assertSame(holder, value.unsetCodeIfMatches("code_other"));
    Assertions.assertTrue(value.getCodeValue().isPresent(), "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetCodeIfMatches("code"));
    Assertions.assertFalse(value.getCodeValue().isPresent(), "The field name must clear the value");
    value.code(vo);
    Assertions.assertSame(holder, value.unsetCode());
    Assertions.assertFalse(value.getCodeValue().isPresent(), "Unset must clear the value");
  }
}
